window.__TNPSC_REGISTER_TEST__("tamil", 1, [{"id":1,"subject":"tamil","testNumber":1,"question":"தமிழ் மொழியில் முதல் எழுத்துகள் என அழைக்கப்படுபவை எவை?","options":["உயிர் எழுத்துகள் 12-ம் மெய் எழுத்துகள் 18-ம்","உயிர் எழுத்துகள் 12-ம் ஆய்த எழுத்து 1-ம்","மெய் எழுத்துகள் 18-ம் உயிர்மெய் எழுத்துகள் 216-ம்","உயிர்மெய் எழுத்துகள் 216-ம் ஆய்த எழுத்து 1-ம்"],"correctAnswer":0,"explanation":"உயிர் எழுத்துகள் பன்னிரண்டும் மெய் எழுத்துகள் பதினெட்டும் ஆகிய முப்பது எழுத்துகளும் முதல் எழுத்துகள் ஆகும். பிற எழுத்துகள் தோன்றுவதற்கும் இயங்குவதற்கும் முதற்காரணமாக இவை அமைவதால் இப்பெயர் பெற்றன.","difficulty":"easy","topic":"எழுத்து இலக்கணம் - முதல் எழுத்துகள்"},{"id":2,"subject":"tamil","testNumber":1,"question":"ஆய்த எழுத்திற்கு வழங்கப்படும் வேறு பெயர்களில் பொருந்தாதது எது?","options":["முப்புள்ளி","தனிநிலை","அஃகேனம்","உடம்படுமெய்"],"correctAnswer":3,"explanation":"ஆய்த எழுத்திற்கு முப்புள்ளி, முப்பாற்புள்ளி, தனிநிலை, அஃகேனம் என்பன வேறு பெயர்களாகும். உடம்படுமெய் என்பது உயிரீற்றுப் புணர்ச்சியில் தோன்றும் 'ய்', 'வ்' மெய்களைக் குறிக்கும்.","difficulty":"easy","topic":"எழுத்து இலக்கணம் - ஆய்த எழுத்து"},{"id":3,"subject":"tamil","testNumber":1,"question":"பின்வரும் மெய்யெழுத்துகளில் இடையின மெய்களின் தொகுப்பு எது?","options":["ய், ர், ல், வ், ழ், ள்","ங், ஞ், ண், ந், ம், ன்","க், ச், ட், த், ப், ற்","க், ங், ச், ஞ், ட், ண்"],"correctAnswer":0,"explanation":"மெய்யெழுத்துகள் ஒலிக்கும் தன்மைக்கேற்ப வல்லினம், மெல்லினம், இடையினம் என மூவகைப்படும். அவற்றுள் வன்மையாகவும் இல்லாமல் மென்மையாகவும் இல்லாமல் இடைப்பட்டு ஒலிக்கும் ய், ர், ல், வ், ழ், ள் ஆகிய ஆறும் இடையின மெய்கள் ஆகும்.","difficulty":"easy","topic":"எழுத்து இலக்கணம் - மெய்யெழுத்துகள்"},{"id":4,"subject":"tamil","testNumber":1,"question":"தமிழில் உள்ள உயிர்மெய் எழுத்துகளில் உயிர்மெய்க் குறில் மற்றும் உயிர்மெய் நெடில் எழுத்துகளின் எண்ணிக்கை முறையே எவ்வளவு?","options":["90 மற்றும் 126","108 மற்றும் 108","72 மற்றும் 144","126 மற்றும் 90"],"correctAnswer":0,"explanation":"மெய்யெழுத்துகள் 18-உடன் உயிர்க் குறில்கள் 5 சேர்வதால் 18 × 5 = 90 உயிர்மெய்க் குறில் எழுத்துகளும், உயிர் நெடில்கள் 7 சேர்வதால் 18 × 7 = 126 உயிர்மெய் நெடில் எழுத்துகளும் பிறக்கின்றன. மொத்தம் 216 உயிர்மெய் எழுத்துகள் ஆகும்.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - உயிர்மெய் எழுத்துகள்"},{"id":5,"subject":"tamil","testNumber":1,"question":"ஆய்த எழுத்து ஒரு சொல்லில் எப்பகுதியில் மட்டுமே இடம்பெறும்?","options":["சொல்லின் முதலில் நெடிலுக்கு முன்","இரண்டு உயிர் நெடில் எழுத்துகளுக்கு இடையில்","சொல்லின் இறுதியில் மெல்லின எழுத்திற்குப் பின்","தனக்கு முன் ஒரு குறிலையும் தனக்குப் பின் ஒரு வல்லின உயிர்மெய்யையும் பெற்றுச் சொல்லின் இடையில்"],"correctAnswer":3,"explanation":"ஆய்த எழுத்து தனக்கு முன் ஒரு குறில் எழுத்தையும் தனக்குப் பின் ஒரு வல்லின உயிர்மெய் எழுத்தையும் பெற்றுச் சொல்லின் இடையில் மட்டுமே வரும் (எ.கா: எஃகு, அஃது, கஃசு). இது ஒரு தனிநிலைச் சார்பெழுத்தாகும்.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - ஆய்த எழுத்து"},{"id":6,"subject":"tamil","testNumber":1,"question":"நன்னூலின்படி சார்பெழுத்துகள் எத்தனை வகைப்படும்?","options":["மூன்று","ஆறு","எட்டு","பத்து"],"correctAnswer":3,"explanation":"நன்னூல் இலக்கணத்தின்படி சார்பெழுத்துகள் பத்து வகைப்படும். அவை: உயிர்மெய், ஆய்தம், உயிரளபெடை, ஒற்றளபெடை, குற்றியலிகரம், குற்றியலுகரம், ஐகாரக்குறுக்கம், ஔகாரக்குறுக்கம், மகரக்குறுக்கம், ஆய்தக்குறுக்கம் என்பனவாகும்.","difficulty":"easy","topic":"எழுத்து இலக்கணம் - சார்பெழுத்துகள்"},{"id":7,"subject":"tamil","testNumber":1,"question":"'கெடுப்பதூஉம் கெட்டார்க்குச் சார்வாய்மற் றாங்கே' என்ற அடியில் அமைந்துள்ள அளபெடை வகை எது?","options":["செய்யுளிசை அளபெடை","சொல்லிசை அளபெடை","ஒற்றளபெடை","இன்னிசை அளபெடை"],"correctAnswer":3,"explanation":"செய்யுளில் ஓசை குறையாத இடத்திலும் இனிய ஓசைக்காகக் குறில் எழுத்து நெடிலாகி அளபெடுப்பது இன்னிசை அளபெடை ஆகும். 'கெடுப்பதூஉம்' என்பதில் 'து' என்ற குறில் 'தூ' என நெடிலாகி 'உ' சேர்ந்து மூவசைச் சீராக அளபெடுத்துள்ளது.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - உயிரளபெடை"},{"id":8,"subject":"tamil","testNumber":1,"question":"'உரனசைஇ உள்ளம் துணையாகச் சென்றார்' என்பதில் 'நசைஇ' என்பது எவ்வகை அளபெடை?","options":["சொல்லிசை அளபெடை","இசைநிறை அளபெடை","இன்னிசை அளபெடை","ஒற்றளபெடை"],"correctAnswer":0,"explanation":"செய்யுளில் ஒரு பெயர்ச்சொல் எச்சப் பொருள் தரும்பொருட்டு அளபெடுப்பது சொல்லிசை அளபெடை எனப்படும். 'நசை' (விருப்பம்) என்ற பெயர்ச்சொல் 'நசைஇ' (விரும்பி) என வினையெச்சப் பொருள் தருவதற்காக அளபெடுத்துள்ளது.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - உயிரளபெடை"},{"id":9,"subject":"tamil","testNumber":1,"question":"ஒற்றளபெடையில் அளபெடுக்கும் எழுத்துகள் மொத்தம் எத்தனை?","options":["ஏழு","பத்து","பதினெட்டு","பதினொன்று"],"correctAnswer":3,"explanation":"ஒற்றளபெடையில் ங், ஞ், ண், ந், ம், ன் ஆகிய ஆறு மெல்லின மெய்களும், வ், ய், ல், ள் ஆகிய நான்கு இடையின மெய்களும், ஃ என்ற ஆய்த எழுத்து ஒன்றும் சேர்த்து மொத்தம் 11 எழுத்துகள் அளபெடுக்கும்.","difficulty":"hard","topic":"எழுத்து இலக்கணம் - ஒற்றளபெடை"},{"id":10,"subject":"tamil","testNumber":1,"question":"செய்யுளிசை அளபெடையின் மற்றொரு பெயர் என்ன?","options":["இன்னிசை அளபெடை","எச்ச அளபெடை","இயற்கை அளபெடை","இசைநிறை அளபெடை"],"correctAnswer":3,"explanation":"செய்யுளில் ஓசை குறையும்போது அதனை நிறைவு செய்ய மொழி முதல், இடை, கடை ஆகிய இடங்களில் நெட்டெழுத்துகள் அளபெடுப்பது செய்யுளிசை அளபெடை ஆகும். ஓசையை நிறைவு செய்வதால் இதற்கு 'இசைநிறை அளபெடை' என்ற வேறு பெயரும் உண்டு.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - உயிரளபெடை"},{"id":11,"subject":"tamil","testNumber":1,"question":"கீழ்க்காணும் சொற்களுள் 'உயிர்த்தொடர்க் குற்றியலுகரம்' அல்லாத சொல் எது?","options":["அரசு","ஒன்பது","கயிறு","பாகு"],"correctAnswer":3,"explanation":"தனிநெடில் அல்லாத உயிர்மெய் எழுத்தைத் தொடர்ந்து வரும் குற்றியலுகரம் உயிர்த்தொடர்க் குற்றியலுகரம் (அரசு, ஒன்பது, கயிறு). ஆனால் 'பாகு' என்பது தனிநெடிலை அடுத்து வரும் ஈரெழுத்துச் சொல்லாதலால் நெடில்தொடர்க் குற்றியலுகரம் ஆகும்.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - குற்றியலுகரம்"},{"id":12,"subject":"tamil","testNumber":1,"question":"'எய்து, மார்பு, சால்பு, மூழ்கு' ஆகிய சொற்கள் எவ்வகைக் குற்றியலுகரத்திற்குச் சான்றுகளாகும்?","options":["மென்தொடர்க் குற்றியலுகரம்","வன்தொடர்க் குற்றியலுகரம்","ஆய்தத்தொடர்க் குற்றியலுகரம்","இடைத்தொடர்க் குற்றியலுகரம்"],"correctAnswer":3,"explanation":"இடையின மெய்யெழுத்துகளைத் (ய், ர், ல், வ், ழ், ள்) தொடர்ந்து குற்றியலுகரம் வந்தால் அது இடைத்தொடர்க் குற்றியலுகரம் எனப்படும். எய்து, மார்பு, சால்பு, மூழ்கு ஆகியவற்றில் இடையின மெய்களை அடுத்து வல்லின உகரம் வந்துள்ளது.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - குற்றியலுகரம்"},{"id":13,"subject":"tamil","testNumber":1,"question":"கீழ்க்கண்டவற்றுள் 'முற்றியலுகரச் சொல்' எது?","options":["பசு","பந்து","பாக்கு","எஃகு"],"correctAnswer":0,"explanation":"தனிக்குறில் எழுத்தை அடுத்துச் சொல்லின் இறுதியில் வரும் வல்லின உகரம் தனது ஒரு மாத்திரை அளவிலிருந்து குறையாமல் முழுமையாக ஒலிக்கும். எனவே 'பசு' என்பது முற்றியலுகரம் ஆகும். மற்ற மூன்றும் முறையே மென்தொடர், வன்தொடர், ஆய்தத்தொடர்க் குற்றியலுகரங்கள்.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - முற்றியலுகரம்"},{"id":14,"subject":"tamil","testNumber":1,"question":"'கேண்மியா' என்ற சொல்லில் இடம்பெற்றுள்ள சார்பெழுத்து எது?","options":["குற்றியலுகரம்","ஐகாரக்குறுக்கம்","மகரக்குறுக்கம்","குற்றியலிகரம்"],"correctAnswer":3,"explanation":"'மியா' என்பது ஓர் அசைச்சொல். இதில் உள்ள மகரத்தின் மேல் ஏறிய இகரம் தனக்குரிய ஒரு மாத்திரையிலிருந்து அரை மாத்திரையாகக் குறைந்து ஒலிக்கும். கேள் + மியா = கேண்மியா என்பது குற்றியலிகரத்திற்குச் சான்றாகும்.","difficulty":"hard","topic":"எழுத்து இலக்கணம் - குற்றியலிகரம்"},{"id":15,"subject":"tamil","testNumber":1,"question":"ஐகாரக்குறுக்கம் சொல்லின் முதல், இடை, கடை ஆகிய இடங்களில் ஒலிக்கும் மாத்திரை அளவுகள் முறையே யாவை?","options":["2, 1.5, 1 மாத்திரை","1.5, 1, 1 மாத்திரை","1.5, 1, 0.5 மாத்திரை","1, 1, 0.5 மாத்திரை"],"correctAnswer":1,"explanation":"ஐகாரம் தனித்து ஒலிக்கும்போது 2 மாத்திரை அளவு பெறும். ஆனால் சொல்லில் சேர்ந்து வரும்போது மொழி முதலில் ஒன்றரை (1.5) மாத்திரையாகவும், மொழி இடையிலும் இறுதியிலும் ஒரு (1) மாத்திரையாகவும் குறைந்து ஒலிக்கும்.","difficulty":"hard","topic":"எழுத்து இலக்கணம் - ஐகாரக்குறுக்கம்"},{"id":16,"subject":"tamil","testNumber":1,"question":"'போன்ம், மருண்ம்' ஆகிய செய்யுள் சொற்களில் இடம்பெற்றுள்ள குறுக்கம் எது?","options":["ஆய்தக்குறுக்கம்","ஔகாரக்குறுக்கம்","குற்றியலிகரம்","மகரக்குறுக்கம்"],"correctAnswer":3,"explanation":"செய்யுளில் 'ண்', 'ன்' ஆகிய மெய்யெழுத்துகளைத் தொடர்ந்து 'ம்' வரும்போதும், 'ம்' எழுத்தைத் தொடர்ந்து 'வ்' வரும்போதும் (எ.கா: வலம் வந்தான்) மகர மெய் தனது அரை மாத்திரையிலிருந்து கால் மாத்திரையாகக் குறைந்து ஒலிக்கும். இது மகரக்குறுக்கம் எனப்படும்.","difficulty":"hard","topic":"எழுத்து இலக்கணம் - மகரக்குறுக்கம்"},{"id":17,"subject":"tamil","testNumber":1,"question":"'ஔகாரக்குறுக்கம்' தொடர்பான கூற்றுகளில் சரியானது எது?","options":["சொல்லின் முதல், இடை, கடை ஆகிய மூன்று இடங்களிலும் வரும்","சொல்லின் இறுதியில் மட்டும் வந்து ஒரு மாத்திரையாக ஒலிக்கும்","சொல்லின் முதலில் மட்டும் வந்து ஒன்றரை மாத்திரையாக ஒலிக்கும்","சொல்லின் இடையில் மட்டும் வந்து அரை மாத்திரையாக ஒலிக்கும்"],"correctAnswer":2,"explanation":"ஔகாரம் சொல்லின் இடையிலும் இறுதியிலும் வராது. சொல்லின் முதலில் மட்டுமே வரும் (எ.கா: ஔவையார், வௌவால்). அப்போது தனக்குரிய இரண்டு மாத்திரையிலிருந்து ஒன்றரை (1.5) மாத்திரையாகக் குறைந்து ஒலிக்கும்.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - ஔகாரக்குறுக்கம்"},{"id":18,"subject":"tamil","testNumber":1,"question":"'அஃறிணை' என்ற சொல்லில் உள்ள ஆய்த எழுத்தின் மாத்திரை அளவு எவ்வளவு?","options":["அரை மாத்திரை","கால் மாத்திரை","ஒரு மாத்திரை","ஒன்றரை மாத்திரை"],"correctAnswer":1,"explanation":"அல் + திணை = அஃறிணை எனப் புணரும்போது 'ல்' ஆய்தமாகவும் 'தி' 'றி' ஆகவும் திரியும். இவ்வாறு புணர்ச்சியால் தோன்றும் ஆய்தம் தனது இயல்பான அரை மாத்திரையிலிருந்து கால் மாத்திரையாகக் குறைந்து ஒலிக்கும். இதனை ஆய்தக்குறுக்கம் என்பர்.","difficulty":"hard","topic":"எழுத்து இலக்கணம் - ஆய்தக்குறுக்கம்"},{"id":19,"subject":"tamil","testNumber":1,"question":"'கபிலர்' என்ற சொல்லின் மொத்த மாத்திரை அளவு எவ்வளவு?","options":["3 மாத்திரை","3.5 மாத்திரை","4 மாத்திரை","4.5 மாத்திரை"],"correctAnswer":1,"explanation":"'கபிலர்' என்ற சொல்லில் க (1) + பி (1) + ல (1) + ர் (0.5) = 3.5 மாத்திரை அளவாகும். உயிர்மெய்க் குறில் ஒவ்வொன்றிற்கும் ஒரு மாத்திரையும், மெய்யெழுத்திற்கு அரை மாத்திரையும் கணக்கிடப்படும்.","difficulty":"easy","topic":"எழுத்து இலக்கணம் - மாத்திரை அளவுகள்"},{"id":20,"subject":"tamil","testNumber":1,"question":"'எஃகு' என்ற சொல்லின் மொத்த மாத்திரை அளவு எவ்வளவு?","options":["2 மாத்திரை","2.5 மாத்திரை","1.5 மாத்திரை","3 மாத்திரை"],"correctAnswer":0,"explanation":"'எஃகு' என்பது ஆய்தத்தொடர்க் குற்றியலுகரச் சொல். இதில் எ (உயிர்க் குறில்) = 1 மாத்திரை, ஃ (ஆய்தம்) = 0.5 மாத்திரை, கு (குற்றியலுகரம்) = 0.5 மாத்திரை. ஆக மொத்தம் 1 + 0.5 + 0.5 = 2 மாத்திரை ஆகும்.","difficulty":"hard","topic":"எழுத்து இலக்கணம் - மாத்திரை அளவுகள்"},{"id":21,"subject":"tamil","testNumber":1,"question":"சுட்டெழுத்தை நீக்கினாலும் பொருள் தருவது எவ்வகைச் சுட்டு?","options":["அகச்சுட்டு","புறச்சுட்டு","சுட்டுத்திரிபு","சேய்மைச்சுட்டு"],"correctAnswer":1,"explanation":"சொல்லின் புறத்தே (வெளியே) இருந்து சுட்டுப் பொருளைத் தருவது புறச்சுட்டு ஆகும். இதில் சுட்டெழுத்தை நீக்கினாலும் எஞ்சிய சொல் பொருள் தரும் (எ.கா: அம்மலை -> மலை, இவ்வானம் -> வானம்).","difficulty":"easy","topic":"எழுத்து இலக்கணம் - சுட்டெழுத்துகள்"},{"id":22,"subject":"tamil","testNumber":1,"question":"'அந்தப் பள்ளி, இந்த நூல்' ஆகிய தொடர்களில் இடம்பெற்றுள்ள இலக்கணக் கூறு எது?","options":["அகச்சுட்டு","புறவினா","சுட்டுத்திரிபு","அண்மைச்சுட்டு மட்டும்"],"correctAnswer":2,"explanation":"அ, இ ஆகிய சுட்டெழுத்துகள் மாற்றம் பெற்று (திரிந்து) 'அந்த', 'இந்த' என வழங்கப்படுவது சுட்டுத்திரிபு எனப்படும். 'அப்பள்ளி' என்பது 'அந்தப் பள்ளி' என்றும், 'இந்நூல்' என்பது 'இந்த நூல்' என்றும் திரிந்துள்ளது.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - சுட்டெழுத்துகள்"},{"id":23,"subject":"tamil","testNumber":1,"question":"வினா எழுத்துகளுள் சொல்லின் முதலிலும் இறுதியிலும் வரும் எழுத்து எது?","options":["எ","யா","ஓ","ஏ"],"correctAnswer":3,"explanation":"வினா எழுத்துகள் எ, யா, ஆ, ஓ, ஏ ஆகிய ஐந்தாகும். அவற்றுள் எ, யா இரண்டும் மொழி முதலிலும்; ஆ, ஓ இரண்டும் மொழி இறுதியிலும்; 'ஏ' என்ற எழுத்து மட்டும் மொழி முதலிலும் (ஏன்) இறுதியிலும் (நீதானே) வரும்.","difficulty":"easy","topic":"எழுத்து இலக்கணம் - வினா எழுத்துகள்"},{"id":24,"subject":"tamil","testNumber":1,"question":"பின்வருவனவற்றுள் 'அகவினா' சொல்லுக்குச் சரியான எடுத்துக்காட்டு எது?","options":["அவனா","வருவானோ","யார்","பேசலாமா"],"correctAnswer":2,"explanation":"வினா எழுத்து சொல்லின் அகத்தே (உள்ளே) இருந்து வினாப் பொருளைத் தருவது அகவினா ஆகும். இதிலிருந்து வினா எழுத்தை நீக்கினால் பிற எழுத்துகளுக்குப் பொருள் இருக்காது (எ.கா: எது, யார், ஏன்). மற்ற மூன்றும் புறவினாக்கள்.","difficulty":"easy","topic":"எழுத்து இலக்கணம் - வினா எழுத்துகள்"},{"id":25,"subject":"tamil","testNumber":1,"question":"தமிழ் இலக்கணப்படி சொல்லின் முதலில் வரும் எழுத்துகள் மொத்தம் எத்தனை?","options":["18","22","24","30"],"correctAnswer":1,"explanation":"நன்னூலின்படி உயிரெழுத்துகள் 12-உம், க, ச, த, ந, ப, ம, வ, ய, ஞ, ங ஆகிய 10 மெய்களின் உயிர்மெய் வடிவங்களும் சேர்த்து மொத்தம் 22 எழுத்துகள் சொல்லின் முதலில் வரும்.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - மொழி முதல் எழுத்துகள்"},{"id":26,"subject":"tamil","testNumber":1,"question":"தமிழ் இலக்கணப்படி சொல்லின் இறுதியில் வராத மெய்யெழுத்துகள் எத்தனை?","options":["5","6","7","8"],"correctAnswer":2,"explanation":"வல்லின மெய்கள் ஆறும் (க், ச், ட், த், ப், ற்) மெல்லினத்தில் 'ங்' என்ற மெய்யும் ஆகிய 7 மெய்யெழுத்துகள் தமிழ்ச் சொல்லின் இறுதியில் வராது. எஞ்சிய 11 மெய்யெழுத்துகளே மொழி இறுதியில் வரும்.","difficulty":"hard","topic":"எழுத்து இலக்கணம் - மொழி இறுதி எழுத்துகள்"},{"id":27,"subject":"tamil","testNumber":1,"question":"பின்வரும் மெய்யெழுத்துகளில் எது தமிழ்ச் சொல்லின் முதலில் வராது?","options":["ஞ","ய","வ","ர"],"correctAnswer":3,"explanation":"ட, ண, ர, ல, ழ, ள, ற, ன ஆகிய எட்டு மெய்களின் வரிசை எழுத்துகள் தமிழ்ச் சொல்லின் முதலில் வராது. 'ஞ' (ஞாயிறு), 'ய' (யானை), 'வ' (வணக்கம்) ஆகியவை மொழி முதலில் வரும்.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - மொழி முதல் எழுத்துகள்"},{"id":28,"subject":"tamil","testNumber":1,"question":"'ங' வரிசை எழுத்துகளில் சொல்லின் முதலில் வரும் ஒரே எழுத்து எது?","options":["ங","ஙா","ஙி","ஙு"],"correctAnswer":0,"explanation":"ஙகர வரிசையில் 'ங' என்ற ஓர் எழுத்து மட்டுமே சொல்லின் முதலில் வரும். அதுவும் இக்காலத்தில் தனித்து வராமல் அ, இ, உ ஆகிய சுட்டெழுத்துகளுடனும் எ, யா ஆகிய வினா எழுத்துகளுடனும் சேர்ந்து (அங்ஙனம், இங்ஙனம், எங்ஙனம்) வருகிறது.","difficulty":"hard","topic":"எழுத்து இலக்கணம் - மொழி முதல் எழுத்துகள்"},{"id":29,"subject":"tamil","testNumber":1,"question":"உயிரெழுத்துகளுள் 'ஐ' மற்றும் 'ஔ' ஆகிய நெடில் எழுத்துகளுக்குரிய இன எழுத்துகள் முறையே யாவை?","options":["அ மற்றும் ஒ","இ மற்றும் உ","எ மற்றும் ஒ","இ மற்றும் அ"],"correctAnswer":1,"explanation":"உயிரெழுத்துகளில் நெடிலுக்குக் குறில் இன எழுத்தாகும். ஆனால் குறில் வடிவம் இல்லாத 'ஐ' என்ற எழுத்திற்கு 'இ' எழுத்தும், 'ஔ' என்ற எழுத்திற்கு 'உ' எழுத்தும் இன எழுத்துகளாகக் கொள்ளப்படுகின்றன (எ.கா: நசைஇ, கெளஉ).","difficulty":"medium","topic":"எழுத்து இலக்கணம் - இன எழுத்துகள்"},{"id":30,"subject":"tamil","testNumber":1,"question":"தமிழ் எழுத்துகளில் இன எழுத்து இல்லாத எழுத்து எது?","options":["யகர மெய்","ஆய்த எழுத்து","றகர மெய்","ஐகார உயிர்"],"correctAnswer":1,"explanation":"உயிர் நெடில்களுக்குக் குறில்களும், வல்லின மெய்களுக்கு மெல்லின மெய்களும் இன எழுத்துகளாகும். இடையின மெய்கள் ஆறும் ஒரே இனமாகும். ஆனால் ஆய்த எழுத்திற்கு இன எழுத்து இல்லை.","difficulty":"easy","topic":"எழுத்து இலக்கணம் - இன எழுத்துகள்"},{"id":31,"subject":"tamil","testNumber":1,"question":"'கன்று, மஞ்சள், பந்தல்' ஆகிய சொற்களில் மெல்லின மெய்களை அடுத்து வல்லின எழுத்துகள் வரக் காரணம் என்ன?","options":["உடம்படுமெய் விதி","இன எழுத்துகளின் அமைப்பு","சுட்டுத்திரிபு விதி","ஒற்றளபெடை விதி"],"correctAnswer":1,"explanation":"தமிழ்ச் சொற்களில் மெல்லின மெய்களை அடுத்துப் பெரும்பாலும் அவற்றின் இனமான வல்லின எழுத்துகளே வரும். ன்-ற் (கன்று), ஞ்-ச (மஞ்சள்), ந்-த (பந்தல்) என்பன இன எழுத்து இணைவுக்குச் சான்றுகளாகும்.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - இன எழுத்துகள்"},{"id":32,"subject":"tamil","testNumber":1,"question":"தமிழில் 'மயங்கொலி எழுத்துகள்' மொத்தம் எத்தனை?","options":["ஆறு","ஏழு","எட்டு","பத்து"],"correctAnswer":2,"explanation":"உச்சரிப்பில் சிறிதளவு மட்டுமே வேறுபாடு உள்ள ஒலிகளை மயங்கொலிகள் என்பர். ண, ன, ந; ல, ள, ழ; ர, ற ஆகிய எட்டு எழுத்துகளும் தமிழ் மொழியின் மயங்கொலி எழுத்துகள் ஆகும்.","difficulty":"easy","topic":"எழுத்து இலக்கணம் - மயங்கொலிகள்"},{"id":33,"subject":"tamil","testNumber":1,"question":"'வலி, வழி, வளி' ஆகிய மயங்கொலிச் சொற்களின் சரியான பொருள் வரிசை எது?","options":["காற்று, பாதை, நோவு","நோவு, பாதை, காற்று","பாதை, நோவு, காற்று","நோவு, காற்று, பாதை"],"correctAnswer":1,"explanation":"மயங்கொலி எழுத்துகள் மாறுவதால் சொற்களின் பொருள் மாறுபடும். இதன்படி 'வலி' என்றால் நோவு (அல்லது வலிமை), 'வழி' என்றால் பாதை, 'வளி' என்றால் காற்று என்பது சரியான பொருள் வரிசையாகும்.","difficulty":"easy","topic":"எழுத்து இலக்கணம் - மயங்கொலிகள்"},{"id":34,"subject":"tamil","testNumber":1,"question":"நாவின் நுனி மேல்வாய்ப் பல்லின் அடிப்பகுதியைத் தொடுவதால் பிறக்கும் மயங்கொலி எழுத்து எது?","options":["ண","ன","ந","ள"],"correctAnswer":2,"explanation":"'ந' (தந்நகரம்) நாவின் நுனி மேல்வாய்ப் பல்லின் அடிப்பகுதியைத் தொடுவதால் பிறக்கும். 'ண' (டண்ணகரம்) மேல்வாயின் நடுப்பகுதியையும், 'ன' (றன்னகரம்) மேல்வாயின் முன்பகுதியையும் நாவின் நுனி தொடுவதால் பிறக்கும்.","difficulty":"hard","topic":"எழுத்து இலக்கணம் - மயங்கொலிகள்"},{"id":35,"subject":"tamil","testNumber":1,"question":"'வாலை, வாழை, வாளை' ஆகிய சொற்களின் பொருத்தமான பொருளைத் தேர்ந்தெடுக்கவும்.","options":["மரம், மீன், இளம்பெண்","இளம்பெண், மரம், மீன்","மீன், இளம்பெண், மரம்","இளம்பெண், மீன், மரம்"],"correctAnswer":1,"explanation":"லகர, ழகர, ளகர வேறுபாட்டால் பொருள் மாறுபடுகிறது. 'வாலை' என்பது இளம்பெண்ணையும், 'வாழை' என்பது வாழை மரத்தையும், 'வாளை' என்பது ஒருவகை மீனையும் குறிக்கும்.","difficulty":"medium","topic":"எழுத்து இலக்கணம் - மயங்கொலிகள்"},{"id":36,"subject":"tamil","testNumber":1,"question":"நிலைமொழியும் வருமொழியும் எவ்வித மாற்றமும் இன்றி இயல்பாக இணைவது எவ்வகைப் புணர்ச்சி?","options":["விகாரப் புணர்ச்சி","இயல்புப் புணர்ச்சி","தோன்றல் விகாரம்","திரிதல் விகாரம்"],"correctAnswer":1,"explanation":"நிலைமொழியும் வருமொழியும் சேரும்போது எழுத்துகளில் எவ்வித மாற்றமும் நிகழாமல் இயல்பாகப் புணர்வது இயல்புப் புணர்ச்சி எனப்படும் (எ.கா: தாய் + மொழி = தாய்மொழி, பொன் + வளையல் = பொன்வளையல்).","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - இயல்புப் புணர்ச்சி"},{"id":37,"subject":"tamil","testNumber":1,"question":"'கல் + சிலை = கற்சிலை' என்பது எவ்வகை விகாரப் புணர்ச்சி ஆகும்?","options":["தோன்றல் விகாரம்","கெடுதல் விகாரம்","திரிதல் விகாரம்","இயல்புப் புணர்ச்சி"],"correctAnswer":2,"explanation":"புணர்ச்சியின்போது ஓர் எழுத்து மற்றோர் எழுத்தாக மாறுவது திரிதல் விகாரம் எனப்படும். 'கல் + சிலை = கற்சிலை' என்பதில் நிலைமொழி ஈற்றிலுள்ள 'ல்' என்ற எழுத்து 'ற்' எனத் திரிந்துள்ளது.","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - விகாரப் புணர்ச்சி"},{"id":38,"subject":"tamil","testNumber":1,"question":"'மனம் + மகிழ்ச்சி = மனமகிழ்ச்சி' என்பதில் நிகழ்ந்துள்ள புணர்ச்சி விகாரம் எது?","options":["தோன்றல்","திரிதல்","கெடுதல்","இரட்டல்"],"correctAnswer":2,"explanation":"புணர்ச்சியின்போது ஓர் எழுத்து மறைவது கெடுதல் விகாரம் எனப்படும். 'மனம் + மகிழ்ச்சி' என்பது புணரும்போது நிலைமொழி ஈற்றிலுள்ள மகர மெய் ('ம்') கெட்டு 'மனமகிழ்ச்சி' எனப் புணர்ந்துள்ளது.","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - விகாரப் புணர்ச்சி"},{"id":39,"subject":"tamil","testNumber":1,"question":"'தமிழ் + தாய் = தமிழ்த்தாய்' என்பது எவ்வகைப் புணர்ச்சிக்குச் சான்றாகும்?","options":["கெடுதல் விகாரப் புணர்ச்சி","திரிதல் விகாரப் புணர்ச்சி","தோன்றல் விகாரப் புணர்ச்சி","இயல்புப் புணர்ச்சி"],"correctAnswer":2,"explanation":"நிலைமொழியும் வருமொழியும் இணையும்போது புதிதாக ஓர் எழுத்துத் தோன்றுவது தோன்றல் விகாரம் எனப்படும். 'தமிழ் + தாய் = தமிழ்த்தாய்' என்பதில் 'த்' என்ற மெய்யெழுத்துப் புதிதாகத் தோன்றியுள்ளது.","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - விகாரப் புணர்ச்சி"},{"id":40,"subject":"tamil","testNumber":1,"question":"புணர்ச்சியைப் பொருள் அடிப்படையில் எத்தனை வகைகளாகப் பிரிப்பர்?","options":["இரண்டு (வேற்றுமைப் புணர்ச்சி, அல்வழிப் புணர்ச்சி)","மூன்று (தோன்றல், திரிதல், கெடுதல்)","நான்கு (உயிரீறு, மெய்யீறு, உயிர்முதல், மெய்ம்முதல்)","ஐந்து (முதல், இடை, கடை, அகம், புறம்)"],"correctAnswer":0,"explanation":"நிலைமொழியும் வருமொழியும் பொருள் தொடர்பால் புணர்வதை வேற்றுமைப் புணர்ச்சி, அல்வழிப் புணர்ச்சி என இரு வகைகளாகப் பிரிப்பர். வேற்றுமை உருபுகள் வெளிப்பட்டோ மறைந்தோ புணர்வது வேற்றுமைப் புணர்ச்சி; அல்லாதவை அல்வழிப் புணர்ச்சி.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - புணர்ச்சி வகைகள்"},{"id":41,"subject":"tamil","testNumber":1,"question":"உயிரீற்றுப் புணர்ச்சியில் நிலைமொழி ஈற்றில் 'இ, ஈ, ஐ' ஆகிய உயிர்கள் நின்று வருமொழி முதலில் உயிர் வந்தால் தோன்றும் உடம்படுமெய் எது?","options":["வ்","ய்","க்","த்"],"correctAnswer":1,"explanation":"'இஈஐ வழி யவ்வும் ஏனை உயிர்வழி வவ்வும் ஏ முன் இவ்விருமையும் உயிர்வரின் உடம்படுமெய் என்றாகும்' என்பது நன்னூல் விதி. எனவே இ, ஈ, ஐ ஆகிய உயிர்களின் பின் உயிர் வந்தால் 'ய்' உடம்படுமெய்யாகத் தோன்றும் (எ.கா: மணி + அடி = மணியடி).","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - உடம்படுமெய்"},{"id":42,"subject":"tamil","testNumber":1,"question":"'பூ + இதழ் = பூவிதழ்' என்ற புணர்ச்சியில் செயல்படும் விதிகள் யாவை?","options":["உயிர்வரின் உக்குறள் மெய்விட்டோடும், உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே","ஏனை உயிர்வழி வவ்வும், உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே","இஈஐ வழி யவ்வும், உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே","தனிக்குறில் முன் ஒற்று உயிர்வரின் இரட்டும், உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே"],"correctAnswer":1,"explanation":"'பூ' என்பது 'ஊ' என்ற உயிரீற்றுச் சொல். இ, ஈ, ஐ அல்லாத பிற உயிர்களின் பின் உயிர் வருவதால் 'ஏனை உயிர்வழி வவ்வும்' என்ற விதிப்படி 'வ்' தோன்றி பூ+வ்+இதழ் என்றாகி, 'உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே' எனப் பூவிதழ் ஆனது.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - உடம்படுமெய்"},{"id":43,"subject":"tamil","testNumber":1,"question":"உடம்படுமெய் விதியில் 'ய்', 'வ்' ஆகிய இரு மெய்களையும் பெற்றுப் புணரும் நிலைமொழி ஈற்று உயிரெழுத்து எது?","options":["ஆ","ஈ","ஏ","ஓ"],"correctAnswer":2,"explanation":"'ஏ முன் இவ்விருமையும்' என்ற நன்னூல் விதிப்படி ஏகார ஈற்று நிலைமொழியின் முன் உயிர் வந்தால் 'ய்' அல்லது 'வ்' ஆகிய இரு உடம்படுமெய்களும் வரும் (எ.கா: சே + அடி = சேயடி, சேவடி; தே + ஆரம் = தேவாரம்).","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - உடம்படுமெய்"},{"id":44,"subject":"tamil","testNumber":1,"question":"'கலை + அழகு' என்பது எவ்வாறு புணரும்?","options":["கலைவழகு","கலையழகு","கலைஅழகு","கலயழகு"],"correctAnswer":1,"explanation":"'கலை' என்ற நிலைமொழியின் ஈற்றில் 'ஐ' உயிர் உள்ளது. 'இஈஐ வழி யவ்வும்' என்ற விதிப்படி 'ய்' உடம்படுமெய் தோன்றி கலை + ய் + அழகு என்றாகி, உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே என்ற விதிப்படி 'கலையழகு' எனப் புணரும்.","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - உடம்படுமெய்"},{"id":45,"subject":"tamil","testNumber":1,"question":"'கோ + இல் = கோவில்' என்ற புணர்ச்சியில் தோன்றிய 'வ்' மெய் எவ்வாறு அழைக்கப்படுகிறது?","options":["ஆய்த எழுத்து","உடம்படுமெய்","சாரியை","இன எழுத்து"],"correctAnswer":1,"explanation":"நிலைமொழியின் இறுதி எழுத்தும் வருமொழியின் முதல் எழுத்தும் உயிரெழுத்துகளாக இருந்தால் அவற்றை உடன்படுத்தி (இணைத்து) ஒலிக்க இடையில் தோன்றும் மெய்யெழுத்து உடம்படுமெய் எனப்படும். கோ + இல் என்பதில் 'வ்' உடம்படுமெய்யாகும்.","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - உடம்படுமெய்"},{"id":46,"subject":"tamil","testNumber":1,"question":"'வாய் + ஒலி = வாயொலி' என்பதில் அமைந்துள்ள புணர்ச்சி விதி எது?","options":["தனிக்குறில் முன் ஒற்று உயிர்வரின் இரட்டும்","உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே","உயிர்வரின் உக்குறள் மெய்விட்டோடும்","இஈஐ வழி யவ்வும்"],"correctAnswer":1,"explanation":"நிலைமொழி ஈற்றில் மெய்யும் ('ய்') வருமொழி முதலில் உயிரும் ('ஒ') வரும்போது அவை இரண்டும் சேர்ந்து உயிர்மெய்யாக ('யொ') மாறும். இதனை 'உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே' என்ற விதி விளக்குகிறது.","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - மெய்யீற்றுப் புணர்ச்சி"},{"id":47,"subject":"tamil","testNumber":1,"question":"'கண் + அழகு = கண்ணழகு' என்ற புணர்ச்சியில் முதலில் செயல்படும் விதி எது?","options":["உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே","தனிக்குறில் முன் ஒற்று உயிர்வரின் இரட்டும்","ஈறுபோதல்","தன்னொற்று இரட்டல்"],"correctAnswer":1,"explanation":"'கண்' என்பதில் தனிக்குறிலை ('க') அடுத்து 'ண்' என்ற ஒற்று உள்ளது. வருமொழி முதலில் 'அ' உயிர் வருவதால் 'தனிக்குறில் முன் ஒற்று உயிர்வரின் இரட்டும்' என்ற விதிப்படி கண்ண் + அழகு என்றாகி, பின்னர் 'உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே' எனக் கண்ணழகு ஆகும்.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - மெய்யீற்றுப் புணர்ச்சி"},{"id":48,"subject":"tamil","testNumber":1,"question":"'வட்டம் + பாறை = வட்டப்பாறை' என்பதில் செயல்படும் மகர ஈற்றுப் புணர்ச்சி விதி எது?","options":["மவ்வீறு ஒற்றழிந்து உயிரீறு ஒப்பவும்","உயிர்வரின் உக்குறள் மெய்விட்டோடும்","முன்னின்ற மெய் திரிதல்","ஆதிநீடல்"],"correctAnswer":0,"explanation":"'மவ்வீறு ஒற்றழிந்து உயிரீறு ஒப்பவும்' என்ற நன்னூல் விதிப்படி வட்டம் என்பதன் ஈற்று மகர ஒற்று ('ம்') கெட்டு 'வட்ட' என உயிரீறு போல் நின்று, வருமொழி வல்லினம் ('ப்') மிகுந்து 'வட்டப்பாறை' எனப் புணர்ந்தது.","difficulty":"hard","topic":"புணர்ச்சி விதிகள் - மெய்யீற்றுப் புணர்ச்சி"},{"id":49,"subject":"tamil","testNumber":1,"question":"'காலம் + கடந்த = காலங்கடந்த' என்ற புணர்ச்சியில் நிகழ்ந்த மாற்றம் எது?","options":["மகர மெய் கெட்டு வல்லினம் மிகுந்தது","மகர மெய் வருமொழி வல்லினத்திற்கு இனமான மெல்லினமாகத் திரிந்தது","உடம்படுமெய் தோன்றியது","தனிக்குறில் முன் ஒற்று இரட்டியது"],"correctAnswer":1,"explanation":"'மவ்வீறு ஒற்றழிந்து உயிரீறு ஒப்பவும் வன்மைக்கு இனமாத் திரிபவும் ஆகும்' என்ற விதிப்படி காலம் + கடந்த என்பதில் உள்ள 'ம்', வருமொழி முதலில் உள்ள 'க' என்ற வல்லினத்திற்கு இனமான 'ங்' என்ற மெல்லினமாகத் திரிந்து 'காலங்கடந்த' என்றானது.","difficulty":"hard","topic":"புணர்ச்சி விதிகள் - மெய்யீற்றுப் புணர்ச்சி"},{"id":50,"subject":"tamil","testNumber":1,"question":"'அருள் + செல்வம்' என்பது எவ்வாறு புணரும்?","options":["அருள்செல்வம்","அருட்செல்வம்","அருற்செல்வம்","அருச்செல்வம்"],"correctAnswer":1,"explanation":"வேற்றுமைப் புணர்ச்சியில் நிலைமொழி ஈற்றிலுள்ள 'ள்' எழுத்து வருமொழி முதலில் வல்லினம் வரும்போது 'ட்' ஆகத் திரியும் ('லள வேற்றுமையில் றடவும்'). எனவே அருள் + செல்வம் = அருட்செல்வம் எனப் புணரும்.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - மெய்யீற்றுப் புணர்ச்சி"},{"id":51,"subject":"tamil","testNumber":1,"question":"'பொன் + தகடு = பொற்றகடு' என்பதில் செயல்படும் மெய்யீற்றுப் புணர்ச்சி விதி எது?","options":["னல முன் றன ஆகும் தநக்கள்","மவ்வீறு ஒற்றழிந்து உயிரீறு ஒப்பவும்","தனிக்குறில் முன் ஒற்று உயிர்வரின் இரட்டும்","இஈஐ வழி யவ்வும்"],"correctAnswer":0,"explanation":"'னல முன் றன ஆகும் தநக்கள்' மற்றும் 'லன வேற்றுமையில் றனவும்' ஆகிய நன்னூல் விதிகளின்படி னகர ஈற்றின் முன் தகரம் வரும்போது னகரம் றகரமாகவும் தகரம் றகரமாகவும் திரிந்து பொன் + தகடு = பொற்றகடு எனப் புணரும்.","difficulty":"hard","topic":"புணர்ச்சி விதிகள் - மெய்யீற்றுப் புணர்ச்சி"},{"id":52,"subject":"tamil","testNumber":1,"question":"'மாசு + அற்றார் = மாசற்றார்' என்ற புணர்ச்சியில் குற்றியலுகரம் கெடக் காரணமான விதி எது?","options":["ஏனை உயிர்வழி வவ்வும்","ஈறுபோதல்","ஆதிநீடல்","உயிர்வரின் உக்குறள் மெய்விட்டோடும்"],"correctAnswer":3,"explanation":"குற்றியலுகர ஈற்றுச் சொல்லின் முன் உயிர் முதல் சொல் வரும்போது, நிலைமொழி ஈற்றிலுள்ள உகரம் தான் ஏறியிருந்த மெய்யை விட்டு ஓடிவிடும். 'மாசு + அற்றார்' -> மாச் + அற்றார் -> 'உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே' -> மாசற்றார்.","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - குற்றியலுகரப் புணர்ச்சி"},{"id":53,"subject":"tamil","testNumber":1,"question":"'வயிறு + பசி = வயிற்றுப்பசி' என்பதில் றகர ஒற்று இரட்டிக்கக் காரணமான விதி எது?","options":["தனிக்குறில் முன் ஒற்று உயிர்வரின் இரட்டும்","தன்னொற்று இரட்டல்","நெடிலோடு உயிர்த்தொடர் குற்றுகரங்களுள் டற ஒற்று இரட்டும் வேற்றுமை மிகவே","முன்னின்ற மெய் திரிதல்"],"correctAnswer":2,"explanation":"'வயிறு' என்பது உயிர்த்தொடர்க் குற்றியலுகரம். நெடில்தொடர் மற்றும் உயிர்த்தொடர்க் குற்றியலுகரங்களில் டகர, றகர ஒற்று வேற்றுமைப் புணர்ச்சியில் இரட்டிக்கும். அதன்படி வயிறு + பசி -> வயிற்று + பசி -> வயிற்றுப்பசி என்றானது.","difficulty":"hard","topic":"புணர்ச்சி விதிகள் - குற்றியலுகரப் புணர்ச்சி"},{"id":54,"subject":"tamil","testNumber":1,"question":"'காடு + எலி' என்பது குற்றியலுகரப் புணர்ச்சி விதிகளின்படி எவ்வாறு புணரும்?","options":["காடெலி","காடுஎலி","காட்டுஎலி","காட்டெலி"],"correctAnswer":3,"explanation":"'காடு' என்பது நெடில்தொடர்க் குற்றியலுகரம். முதலில் டகர ஒற்று இரட்டி 'காட்டு + எலி' என்றாகி, பின் 'உயிர்வரின் உக்குறள் மெய்விட்டோடும்' விதிப்படி 'காட்ட் + எலி' என்றாகி, 'உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே' எனக் 'காட்டெலி' ஆகும்.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - குற்றியலுகரப் புணர்ச்சி"},{"id":55,"subject":"tamil","testNumber":1,"question":"'கதவு + அழகு = கதவழகு' என்பது எவ்வகைப் புணர்ச்சிக்குச் சான்றாகும்?","options":["முற்றியலுகரப் புணர்ச்சி","ஆய்தத்தொடர்க் குற்றியலுகரப் புணர்ச்சி","பண்புப்பெயர்ப் புணர்ச்சி","உடம்படுமெய்ப் புணர்ச்சி"],"correctAnswer":0,"explanation":"'கதவு' என்பது வல்லினம் அல்லாத உகரத்தில் முடிவதால் முற்றியலுகரச் சொல் ஆகும். 'முற்றுமற்று ஒரோவழி' என்ற விதிப்படி முற்றியலுகரத்தின் முன் உயிர் வந்தாலும் சில இடங்களில் உகரம் மெய்விட்டோடி 'கதவ் + அழகு = கதவழகு' எனப் புணரும்.","difficulty":"hard","topic":"புணர்ச்சி விதிகள் - குற்றியலுகரப் புணர்ச்சி"},{"id":56,"subject":"tamil","testNumber":1,"question":"பண்புப்பெயர்ப் புணர்ச்சியில் 'ஈறுபோதல்' என்ற ஒரு விதி மட்டுமே செயல்பட்டுப் புணர்ந்த சொல் எது?","options":["செம்பரிதி","செந்தமிழ்","கருங்கடல்","மூதூர்"],"correctAnswer":0,"explanation":"'செம்மை + பரிதி' என்பதில் 'ஈறுபோதல்' என்ற விதிப்படி 'மை' ஈறு மட்டும் கெட்டு 'செம் + பரிதி = செம்பரிதி' எனப் புணர்ந்துள்ளது. ஆனால் செந்தமிழில் முன்னின்ற மெய் திரிதலும், கருங்கடலில் இனமிகலும், மூதூரில் ஆதிநீடலும் கூடுதலாக நிகழ்ந்துள்ளன.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - பண்புப்பெயர்ப் புணர்ச்சி"},{"id":57,"subject":"tamil","testNumber":1,"question":"'மூதூர்' என்ற சொல்லைப் பிரித்து எழுதினால் கிடைக்கும் சரியான வடிவம் எது?","options":["மூது + ஊர்","மூத்த + ஊர்","முதுமை + ஊர்","மூதுமை + ஊர்"],"correctAnswer":2,"explanation":"'மூதூர்' என்பது 'முதுமை + ஊர்' எனப் பிரியும். இதில் ஈறுபோதல் (முது+ஊர்), ஆதிநீடல் (மூது+ஊர்), உயிர்வரின் உக்குறள் மெய்விட்டோடும் (மூத்+ஊர்), உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே (மூதூர்) ஆகிய நான்கு விதிகள் செயல்பட்டுள்ளன.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - பண்புப்பெயர்ப் புணர்ச்சி"},{"id":58,"subject":"tamil","testNumber":1,"question":"'பைந்தமிழ்' என்ற சொல்லில் முதன்மைப் பண்புப்பெயர்ப் புணர்ச்சி விதியாக அமைந்துள்ள 'அடியகரம் ஐயாதல்' எதனால் நிகழ்ந்தது?","options":["பைமை + தமிழ் என்ற பிரிப்பால்","பசுமை + தமிழ் என்பதில் உள்ள 'ப' என்ற அடியகரம் 'பை' என மாறியதால்","பச்சை + தமிழ் என்பதில் 'ச்' கெட்டதால்","பை + தமிழ் என்பதில் உடம்படுமெய் தோன்றியதால்"],"correctAnswer":1,"explanation":"'பைந்தமிழ்' என்பது 'பசுமை + தமிழ்' எனப் பிரியும். ஈறுபோதல் விதிப்படி 'பசு + தமிழ்' என்றாகி, 'அடியகரம் ஐயாதல்' விதிப்படி 'ப' என்பது 'பை' ஆக மாறி, 'சு' கெட்டு, 'இனமிகல்' விதிப்படி 'ந்' மிகுந்து 'பைந்தமிழ்' எனப் புணர்ந்தது.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - பண்புப்பெயர்ப் புணர்ச்சி"},{"id":59,"subject":"tamil","testNumber":1,"question":"'வெறுமை + இலை = வெற்றிலை' என்ற பண்புப்பெயர்ப் புணர்ச்சியில் 'று' என்பது 'ற்று' ஆக மாறிய விதி எது?","options":["ஆதிநீடல்","இனமிகல்","முன்னின்ற மெய் திரிதல்","தன்னொற்று இரட்டல்"],"correctAnswer":3,"explanation":"'வெறுமை + இலை' என்பதில் 'ஈறுபோதல்' விதிப்படி 'வெறு + இலை' என்றாகி, 'தன்னொற்று இரட்டல்' விதிப்படி றகர ஒற்று இரட்டி 'வெற்று + இலை' என்றாகி, உயிர்வரின் உக்குறள் மெய்விட்டோடும் மற்றும் உடல்மேல் உயிர்வந்து ஒன்றுவது இயல்பே என 'வெற்றிலை' ஆனது.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - பண்புப்பெயர்ப் புணர்ச்சி"},{"id":60,"subject":"tamil","testNumber":1,"question":"'பெருமை + அன் = பெரியன்' என்பதில் 'ரு' என்ற உகரம் 'ரி' என மாறக் காரணமான பண்புப்பெயர் விதி எது?","options":["இடைஉகரம் இய்யாதல்","அடியகரம் ஐயாதல்","ஆதிநீடல்","உயிர்வரின் உக்குறள் மெய்விட்டோடும்"],"correctAnswer":0,"explanation":"'பெருமை + அன்' என்பதில் ஈறுபோதல் விதிப்படி 'பெரு + அன்' என்றாகி, 'இடைஉகரம் இய்யாதல்' என்ற விதிப்படி இடையில் உள்ள உகரம் இகரமாகத் திரிந்து 'பெரி + அன்' என்றாகி, உடம்படுமெய் 'ய்' பெற்று 'பெரியன்' எனப் புணர்ந்தது.","difficulty":"hard","topic":"புணர்ச்சி விதிகள் - பண்புப்பெயர்ப் புணர்ச்சி"},{"id":61,"subject":"tamil","testNumber":1,"question":"'செம்மை + கதிர் = செங்கதிர்' என்பதில் 'ம்' என்ற மெய் 'ங்' ஆக மாறிய விதி எது?","options":["இனமிகல்","தன்னொற்று இரட்டல்","ஆதிநீடல்","முன்னின்ற மெய் திரிதல்"],"correctAnswer":3,"explanation":"'செம்மை + கதிர்' என்பதில் ஈறுபோதல் விதிப்படி 'செம் + கதிர்' என்றாகி, வருமொழி முதலில் உள்ள 'க' எழுத்திற்கு முன்னின்ற 'ம்' என்ற மெய் 'ங்' ஆகத் திரிந்தது. இதனை 'முன்னின்ற மெய் திரிதல்' என்ற பண்புப்பெயர் விதி விளக்குகிறது.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - பண்புப்பெயர்ப் புணர்ச்சி"},{"id":62,"subject":"tamil","testNumber":1,"question":"'கருமை + கடல் = கருங்கடல்' என்ற புணர்ச்சியில் 'ங்' என்ற மெய் புதிதாகத் தோன்றக் காரணமான விதி எது?","options":["முன்னின்ற மெய் திரிதல்","தன்னொற்று இரட்டல்","இனமிகல்","இடைஉகரம் இய்யாதல்"],"correctAnswer":2,"explanation":"'கருமை + கடல்' என்பதில் ஈறுபோதல் விதிப்படி 'கரு + கடல்' என்றாகி, வருமொழி முதலில் உள்ள வல்லினமான 'க' எழுத்திற்கு இனமான 'ங்' என்ற மெல்லினம் புதிதாக மிகுந்து 'கருங்கடல்' ஆனது. இதனை 'இனமிகல்' என்பர்.","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - பண்புப்பெயர்ப் புணர்ச்சி"},{"id":63,"subject":"tamil","testNumber":1,"question":"'கிழக்கு + திசை' என்பது திசைப்பெயர்ப் புணர்ச்சி விதிப்படி எவ்வாறு புணரும்?","options":["கிழக்குத்திசை","கீழ்த்திசை","கிழத்திசை","கீழ்திசை"],"correctAnswer":1,"explanation":"திசைப்பெயர்ப் புணர்ச்சி விதிகளின்படி 'கிழக்கு + திசை' என்பதில் ஈற்றுக் 'கு'கரமும் 'க்' என்ற மெய்யும் கெட்டு, முதலெழுத்து நீண்டு ('கி' -> 'கீ') 'கீழ் + திசை' என்றாகி வல்லினம் மிகுந்து 'கீழ்த்திசை' எனப் புணரும்.","difficulty":"hard","topic":"புணர்ச்சி விதிகள் - திசைப்பெயர்ப் புணர்ச்சி"},{"id":64,"subject":"tamil","testNumber":1,"question":"'தென்கிழக்கு' என்ற திசைப்பெயர்ச் சொல்லைச் சரியாகப் பிரித்து எழுதுக.","options":["தென் + கிழக்கு","தென்மை + கிழக்கு","தெற்கு + கிழக்கு","தென்கிழ + கு"],"correctAnswer":2,"explanation":"'தென்கிழக்கு' என்ற திசைப்பெயர் 'தெற்கு + கிழக்கு' எனப் பிரியும். புணரும்போது நிலைமொழி ஈற்றிலுள்ள 'கு' கெட்டு, எஞ்சிய 'ற்' என்ற மெய் 'ன்' எனத் திரிந்து 'தென்கிழக்கு' என்றாகும்.","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - திசைப்பெயர்ப் புணர்ச்சி"},{"id":65,"subject":"tamil","testNumber":1,"question":"'மேற்கு + திசை' என்பதைச் சேர்த்து எழுதினால் கிடைக்கும் சரியான சொல் எது?","options":["மேற்றிசை","மேற்குதிசை","மேல்திசை","மேற்க்த்திசை"],"correctAnswer":0,"explanation":"திசைப்பெயர்ப் புணர்ச்சி விதிப்படி 'மேற்கு + திசை' என்பதில் ஈற்று 'கு' கெட்டு 'மேற் + திசை' என்றாகி, றகரத்தின் முன் வந்த தகரம் றகரமாகத் திரிந்து 'மேற்றிசை' எனப் புணரும்.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - திசைப்பெயர்ப் புணர்ச்சி"},{"id":66,"subject":"tamil","testNumber":1,"question":"எண்ணுப்பெயர்ப் புணர்ச்சி விதிகளின்படி 'ஒன்பது + பத்து' என்பது எவ்வாறு புணரும்?","options":["ஒன்பதுபத்து","ஒன்பதின்பத்து","தொண்ணூறு","தொள்ளாயிரம்"],"correctAnswer":2,"explanation":"நன்னூல் எண்ணுப்பெயர்ப் புணர்ச்சி விதிகளின்படி 'ஒன்பது + பத்து' என்பது 'தொண்ணூறு' என்றும், 'ஒன்பது + நூறு' என்பது 'தொள்ளாயிரம்' என்றும் புணரும். தொண்ணூறு என்பது ஒன்பது பத்துகளைக் குறிக்கும்.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - எண்ணுப்பெயர்ப் புணர்ச்சி"},{"id":67,"subject":"tamil","testNumber":1,"question":"'பத்து + இரண்டு = பன்னிரண்டு' என்ற எண்ணுப்பெயர்ப் புணர்ச்சியில் 'பத்து' என்பது முதலில் எவ்வாறு திரிந்து பின் ஒற்று இரட்டியது?","options":["பன் எனத் திரிந்து","பம் எனத் திரிந்து","பல் எனத் திரிந்து","பற் எனத் திரிந்து"],"correctAnswer":0,"explanation":"'பத்து + இரண்டு' என்பதில் ஈற்றுத் 'து' மற்றும் தகர ஒற்று கெட்டு 'இன்' சாரியை சேர்ந்து 'பன் + இரண்டு' என்றாகி, 'தனிக்குறில் முன் ஒற்று உயிர்வரின் இரட்டும்' விதிப்படி 'பன்னிரண்டு' எனப் புணர்ந்தது.","difficulty":"hard","topic":"புணர்ச்சி விதிகள் - எண்ணுப்பெயர்ப் புணர்ச்சி"},{"id":68,"subject":"tamil","testNumber":1,"question":"'ஓராயிரம்' என்ற எண்ணுப்பெயர்ச் சொல்லைப் பிரித்து எழுதுக.","options":["ஓர் + ஆயிரம்","ஒரு + ஆயிரம்","ஒன்று + ஆயிரம்","ஒன்ற + ஆயிரம்"],"correctAnswer":2,"explanation":"'ஓராயிரம்' என்ற எண்ணுப்பெயரின் இயல்பான பிரிப்பு 'ஒன்று + ஆயிரம்' ஆகும். புணரும்போது 'ஒன்று' என்பதன் ஈற்று றுகரமும் னகரமும் கெட்டு, 'ர' தோன்றி, முதலெழுத்து நீண்டு ('ஒ' -> 'ஓ') ஓர் + ஆயிரம் = ஓராயிரம் ஆனது.","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - எண்ணுப்பெயர்ப் புணர்ச்சி"},{"id":69,"subject":"tamil","testNumber":1,"question":"'பூ + சோலை = பூஞ்சோலை' என்பதில் செயல்படும் சிறப்புப் புணர்ச்சி விதி எது?","options":["இனமிகல்","பூப்பெயர் முன் இனமென்மையும் தோன்றும்","மவ்வீறு ஒற்றழிந்து உயிரீறு ஒப்பவும்","உடம்படுமெய் விதி"],"correctAnswer":1,"explanation":"'பூப்பெயர் முன் இனமென்மையும் தோன்றும்' என்ற நன்னூல் விதிப்படி, 'பூ' என்ற நிலைமொழியின் முன் வல்லினம் வரும்போது வல்லினத்திற்கு இனமான மெல்லினமும் தோன்றும் (எ.கா: பூ + சோலை = பூஞ்சோலை, பூ + கொடி = பூங்கொடி).","difficulty":"medium","topic":"புணர்ச்சி விதிகள் - சேர்த்து எழுதுக"},{"id":70,"subject":"tamil","testNumber":1,"question":"'பழந்தமிழ்' என்ற சொல்லைப் பிரித்து எழுதுக.","options":["பழம் + தமிழ்","பழைய + தமிழ்","பழ + தமிழ்","பழமை + தமிழ்"],"correctAnswer":3,"explanation":"'பழந்தமிழ்' என்பது பண்புத்தொகைச் சொல் ஆதலால் 'பழமை + தமிழ்' எனப் பிரியும். இதில் 'ஈறுபோதல்' விதிப்படி 'மை' கெட்டு 'பழ + தமிழ்' என்றாகி, 'இனமிகல்' விதிப்படி தகரத்திற்கு இனமான 'ந்' மிகுந்து 'பழந்தமிழ்' என்றானது.","difficulty":"easy","topic":"புணர்ச்சி விதிகள் - பிரித்து எழுதுக"},{"id":71,"subject":"tamil","testNumber":1,"question":"இந்திய நாட்டை 'மொழிகளின் காட்சிசாலை' என்று குறிப்பிட்ட மொழியியல் அறிஞர் யார்?","options":["ச. அகத்தியலிங்கம்","ராபர்ட் கால்டுவெல்","தேவநேயப் பாவாணர்","தெ.பொ. மீனாட்சிசுந்தரனார்"],"correctAnswer":0,"explanation":"இந்தியாவில் 1300-க்கும் மேற்பட்ட மொழிகள் பேசப்படுவதால், மொழியியல் அறிஞர் ச. அகத்தியலிங்கம் இந்திய நாட்டை 'மொழிகளின் காட்சிசாலை' என்று குறிப்பிட்டுள்ளார்.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - உலக மொழிகள்"},{"id":72,"subject":"tamil","testNumber":1,"question":"இந்தியாவில் பேசப்படும் மொழிகளை எத்தனை மொழிக் குடும்பங்களாகப் பிரித்துள்ளனர்?","options":["மூன்று","ஐந்து","ஆறு","நான்கு"],"correctAnswer":3,"explanation":"இந்தியாவில் பேசப்படும் மொழிகளை இந்தோ-ஆசிய மொழிகள், திராவிட மொழிகள், ஆஸ்திரோ-ஆசிய மொழிகள், சீன-திபெத்திய மொழிகள் என நான்கு மொழிக் குடும்பங்களாக மொழியியல் அறிஞர்கள் பிரித்துள்ளனர்.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - உலக மொழிகள்"},{"id":73,"subject":"tamil","testNumber":1,"question":"'திராவிடா' என்ற சொல்லை முதன்முதலில் குறிப்பிட்டவர் யார்?","options":["பிரான்சிஸ் எல்லிஸ்","ஹீராஸ் பாதிரியார்","குமரிலபட்டர்","வில்லியம் ஜோன்ஸ்"],"correctAnswer":2,"explanation":"'திராவிடா' என்ற சொல்லை முதன்முதலில் குறிப்பிட்டவர் குமரிலபட்டர் ஆவார். தமிழ் என்ற சொல்லிலிருந்துதான் 'திராவிடா' என்ற சொல் பிறந்தது என்பதை மொழி ஆய்வாளர்கள் உறுதிப்படுத்தியுள்ளனர்.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - திராவிட மொழிக் குடும்பம்"},{"id":74,"subject":"tamil","testNumber":1,"question":"1856-ஆம் ஆண்டு 'திராவிட மொழிகளின் ஒப்பிலக்கணம்' என்ற நூலை வெளியிட்ட அறிஞர் யார்?","options":["ராபர்ட் கால்டுவெல்","ஜி.யு. போப்","வீரமாமுனிவர்","மாக்ஸ் முல்லர்"],"correctAnswer":0,"explanation":"1856-ஆம் ஆண்டு ராபர்ட் கால்டுவெல் 'திராவிட மொழிகளின் ஒப்பிலக்கணம்' என்ற வரலாற்றுச் சிறப்புமிக்க நூலை வெளியிட்டார். திராவிட மொழிகள் ஆரிய மொழிக் குடும்பத்திலிருந்து வேறுபட்டவை என இந்நூலில் நிறுவினார்.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - திராவிட மொழிக் குடும்பம்"},{"id":75,"subject":"tamil","testNumber":1,"question":"தமிழ், தெலுங்கு, கன்னடம், மலையாளம் ஆகிய மொழிகளை ஒப்புமைப்படுத்தி அவற்றிற்குத் 'தென்னிந்திய மொழிகள்' எனப் பெயரிட்டவர் யார்?","options":["வில்லியம் கேரி","பிரான்சிஸ் எல்லிஸ்","ஸ்டென் கனோ","எம்.பி. எமனோ"],"correctAnswer":1,"explanation":"1816-ஆம் ஆண்டு பிரான்சிஸ் எல்லிஸ் தமிழ், தெலுங்கு, கன்னடம், மலையாளம் போன்ற மொழிகளை ஒப்புமைப்படுத்தி ஆய்ந்து, இவை தனி ஒரு மொழிக் குடும்பத்தைச் சேர்ந்தவை எனக் கூறி அவற்றிற்குத் 'தென்னிந்திய மொழிகள்' எனப் பெயரிட்டார்.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - திராவிட மொழிக் குடும்பம்"},{"id":76,"subject":"tamil","testNumber":1,"question":"'தமிழ் -> தமிழா -> தமிலா -> டிரமிலா -> ட்ரமிலா -> த்ராவிடா -> திராவிடா' எனச் சொல் மாற்றம் நிகழ்ந்ததாகக் குறிப்பிட்ட அறிஞர் யார்?","options":["ராபர்ட் கால்டுவெல்","மாக்ஸ் முல்லர்","கமில் சுவலபில்","ஹீராஸ் பாதிரியார்"],"correctAnswer":3,"explanation":"'தமிழ்' என்ற சொல்லிலிருந்துதான் 'திராவிடா' என்ற சொல் உருவானது என்பதைப் படிப்படியான ஒலி மாற்றத்தின் மூலம் விளக்கிக் காட்டிய மொழி ஆய்வாளர் ஹீராஸ் பாதிரியார் ஆவார்.","difficulty":"hard","topic":"தமிழ் மொழியின் சிறப்புகள் - திராவிட மொழிக் குடும்பம்"},{"id":77,"subject":"tamil","testNumber":1,"question":"பின்வருவனவற்றுள் 'வட திராவிட மொழி'ப் பிரிவைச் சேர்ந்த மொழி எது?","options":["பிராகுய்","துளு","கோலாமி","குடகு"],"correctAnswer":0,"explanation":"வட திராவிட மொழிகள் குரூக், மால்தோ, பிராகுய் ஆகிய மூன்றாகும். இவற்றுள் பிராகுய் மொழி பாகிஸ்தானின் பலுசிஸ்தான் பகுதியில் பேசப்படுகிறது. துளு, குடகு ஆகியன தென் திராவிட மொழிகள்; கோலாமி நடு திராவிட மொழி.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - திராவிட மொழிக் குடும்பம்"},{"id":78,"subject":"tamil","testNumber":1,"question":"தெலுங்கு, கூயி, கோண்டா, கோலாமி ஆகிய மொழிகள் திராவிட மொழிக் குடும்பத்தின் எந்தப் பிரிவைச் சேர்ந்தவை?","options":["தென் திராவிட மொழிகள்","வட திராவிட மொழிகள்","நடு திராவிட மொழிகள்","கிழக்குத் திராவிட மொழிகள்"],"correctAnswer":2,"explanation":"நில அடிப்படையில் திராவிட மொழிகள் தென், நடு, வட திராவிட மொழிகள் என மூவகையாகப் பிரிக்கப்பட்டுள்ளன. அவற்றுள் தெலுங்கு, கூயி, கூவி, கோண்டா, கோலாமி, நாய்க்கி, பெங்கோ, மண்டா, பர்ஜி, கதபா, கோண்டி, கோயா ஆகிய 12-உம் நடு திராவிட மொழிகள் ஆகும்.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - திராவிட மொழிக் குடும்பம்"},{"id":79,"subject":"tamil","testNumber":1,"question":"இந்திய அரசால் தமிழ் மொழி முதன்முதலில் 'செம்மொழி'யாக அறிவிக்கப்பட்ட நாள் எது?","options":["2004 அக்டோபர் 12","2005 நவம்பர் 14","2006 ஜூன் 10","2008 அக்டோபர் 31"],"correctAnswer":0,"explanation":"2004-ஆம் ஆண்டு அக்டோபர் 12-ஆம் நாள் இந்திய அரசால் தமிழ் மொழி இந்தியாவின் முதல் செம்மொழியாக அதிகாரப்பூர்வமாக அறிவிக்கப்பட்டது. அதன் பிறகே சமஸ்கிருதம், கன்னடம், தெலுங்கு, மலையாளம், ஒடியா ஆகியவை அறிவிக்கப்பட்டன.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - செம்மொழி அறிவிப்பு"},{"id":80,"subject":"tamil","testNumber":1,"question":"செம்மொழித் தமிழாய்வு மத்திய நிறுவனம் (CICT) தற்போது எங்கு அமைந்துள்ளது?","options":["தஞ்சாவூர்","மதுரை","மைசூரு","சென்னை"],"correctAnswer":3,"explanation":"செம்மொழித் தமிழாய்வு மத்திய நிறுவனம் 2006-இல் மைசூரில் தொடங்கப்பட்டு, 2008-ஆம் ஆண்டு தமிழ்நாட்டின் தலைநகரான சென்னைக்கு மாற்றப்பட்டது. இது தமிழ் மொழியின் செவ்வியல் ஆய்வுகளை மேற்கொண்டு வருகிறது.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - செம்மொழி அறிவிப்பு"},{"id":81,"subject":"tamil","testNumber":1,"question":"தமிழை முதன்முதலில் 'உயர்தனிச் செம்மொழி' என்று குறிப்பிட்ட தமிழ் அறிஞர் யார்?","options":["மறைமலை அடிகள்","உ.வே. சாமிநாதையர்","பரிதிமாற் கலைஞர்","திரு.வி. கல்யாணசுந்தரனார்"],"correctAnswer":2,"explanation":"பரிதிமாற் கலைஞர் (வி.கோ. சூரியநாராயண சாஸ்திரியார்) தமது 'தமிழ் மொழியின் வரலாறு' நூலிலும் கட்டுரைகளிலும் தமிழ் மொழியை முதன்முதலில் 'உயர்தனிச் செம்மொழி' என அழைத்து அதன் செவ்வியல் தகுதியை நிலைநாட்டினார்.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - செம்மொழித் தகுதிகள்"},{"id":82,"subject":"tamil","testNumber":1,"question":"அமெரிக்காவின் கலிபோர்னியா பல்கலைக்கழகத் தமிழ்ப் பேராசிரியராகப் பணியாற்றித் தமிழ் ஒரு செம்மொழி என்பதை உலகறியச் செய்தவர் யார்?","options":["கமில் சுவலபில்","ராபர்ட் கால்டுவெல்","ஜி.யு. போப்","ஜார்ஜ் எல். ஹார்ட்"],"correctAnswer":3,"explanation":"கலிபோர்னியா பல்கலைக்கழகத் தமிழ்ப் பேராசிரியர் ஜார்ஜ் எல். ஹார்ட், தமிழ் மொழி தொன்மையானதும் பிற மொழிகளின் துணையின்றித் தனித்து இயங்கும் ஆற்றலும் கொண்ட செம்மொழி என்பதைத் தகுந்த சான்றுகளுடன் 2000-ஆம் ஆண்டில் அறிக்கையாக வெளியிட்டார்.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - செம்மொழித் தகுதிகள்"},{"id":83,"subject":"tamil","testNumber":1,"question":"ஒரு மொழி செம்மொழியாகத் தகுதி பெறுவதற்குரிய பதினொரு கோட்பாடுகளுள் பொருந்தாதது எது?","options":["தொன்மை மற்றும் தனித்தன்மை","பிற மொழித் தாக்கமின்மை","பிற மொழி இலக்கணத்தைச் சார்ந்திருத்தல்","உயர் சிந்தனை மற்றும் நடுவுநிலைமை"],"correctAnswer":2,"explanation":"தொன்மை, தனித்தன்மை, பொதுமைப்பண்பு, நடுவுநிலைமை, தாய்மைப்பண்பு, பண்பாட்டுக் கலை அறிவுப் பட்டறிவு வெளிப்பாடு, பிற மொழித் தாக்கமின்மை, இலக்கிய வளம், உயர் சிந்தனை, கலை இலக்கியத் தனித்தன்மை, மொழிக் கோட்பாடு ஆகிய 11-உம் செம்மொழித் தகுதிகளாகும். பிற மொழி இலக்கணத்தைச் சார்ந்திருத்தல் செம்மொழித் தகுதி அன்று.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - செம்மொழித் தகுதிகள்"},{"id":84,"subject":"tamil","testNumber":1,"question":"தமிழ்நாட்டில் கிடைத்துள்ள மிகப் பழமையான குகைக் கல்வெட்டுகளில் காணப்படும் தமிழ் எழுத்து வடிவம் எவ்வாறு அழைக்கப்படுகிறது?","options":["தமிழி (தமிழ் பிராமி)","கிரந்த எழுத்து","கோலெழுத்து","நாகரி எழுத்து"],"correctAnswer":0,"explanation":"கி.மு. 3-ஆம் நூற்றாண்டு முதல் கி.பி. 3-ஆம் நூற்றாண்டு வரையிலான காலகட்டத்தில் தமிழ்நாட்டின் குகைக் கல்வெட்டுகளிலும் பானை ஓடுகளிலும் காணப்படும் மிகப் பழமையான எழுத்து வடிவம் 'தமிழி' (தமிழ் பிராமி) என அழைக்கப்படுகிறது.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - எழுத்து வடிவங்களின் பரிணாமம்"},{"id":85,"subject":"tamil","testNumber":1,"question":"வளைந்த கோடுகளால் அமைந்த மிகப் பழமையான தமிழ் எழுத்து வடிவம் எவ்வாறு அழைக்கப்படுகிறது?","options":["கண்ணெழுத்து","வட்டெழுத்து","தமிழி எழுத்து","புள்ளியெழுத்து"],"correctAnswer":1,"explanation":"பனையோலைகளில் எழுத்தாணியால் எழுதும்போது ஓலை கிழியாமல் இருக்க வளைந்த கோடுகளாக உருவான பழமையான தமிழ் எழுத்து வடிவம் 'வட்டெழுத்து' எனப்படும். சேர, பாண்டிய மண்டலக் கல்வெட்டுகளில் இவ்வெழுத்து மிகுதியாகக் காணப்படுகிறது.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - எழுத்து வடிவங்களின் பரிணாமம்"},{"id":86,"subject":"tamil","testNumber":1,"question":"'கண்ணெழுத்துப் படுத்த எண்ணுப் பல்பொதி' எனப் பண்டைய தமிழ் எழுத்து வடிவமான கண்ணெழுத்தைப் பற்றிக் குறிப்பிடும் நூல் எது?","options":["தொல்காப்பியம்","நன்னூல்","சிலப்பதிகாரம்","மணிமேகலை"],"correctAnswer":2,"explanation":"பண்டைய தமிழகத்தில் வணிகப் பொதிகளின் மீது அடையாளமாக இடப்பட்ட ஓவிய வடிவிலான தமிழ் எழுத்து 'கண்ணெழுத்து' எனப்பட்டது. இதனைச் சிலப்பதிகாரத்தின் இந்திரவிழா ஊரெடுத்த காதை 'கண்ணெழுத்துப் படுத்த எண்ணுப் பல்பொதி' எனக் குறிப்பிடுகிறது.","difficulty":"hard","topic":"தமிழ் மொழியின் சிறப்புகள் - எழுத்து வடிவங்களின் பரிணாமம்"},{"id":87,"subject":"tamil","testNumber":1,"question":"தமிழ் எழுத்துகளில் எகர, ஒகரக் குறில் நெடில் வேறுபாடுகளைக் காட்டப் புள்ளிகளுக்குப் பதிலாகக் கீற்று மற்றும் இரட்டைக் கொம்புச் சீர்திருத்தத்தைச் செய்தவர் யார்?","options":["வீரமாமுனிவர்","பெரியார் ஈ.வெ.ரா.","ஜி.யு. போப்","சீகன்பால்கு"],"correctAnswer":0,"explanation":"பண்டைய தமிழ் எழுத்துகளில் எ, ஒ என்ற குறில்களின் மேல் புள்ளி இடும் வழக்கம் இருந்தது. வீரமாமுனிவர் (கான்ஸ்டான்டின் ஜோசப் பெஸ்கி) புள்ளிகளை நீக்கி ஏ, ஓ ஆகிய நெடில்களுக்குக் கீற்று மற்றும் இரட்டைக் கொம்பு அமைத்து எழுத்துச் சீர்திருத்தம் செய்தார்.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - எழுத்துச் சீர்திருத்தம்"},{"id":88,"subject":"tamil","testNumber":1,"question":"பெரியார் ஈ.வெ.ரா. அவர்களின் தமிழ் எழுத்துச் சீர்திருத்தத்தைத் தமிழ்நாடு அரசு எந்த ஆண்டு அதிகாரப்பூர்வமாக நடைமுறைப்படுத்தியது?","options":["1935","1968","1978","1981"],"correctAnswer":2,"explanation":"பெரியார் 1935-ஆம் ஆண்டு 'குடியரசு' இதழில் ணா, னா, றா, ணை, னை, லை, ளை போன்ற உயிர்மெய் எழுத்துகளின் வரிவடிவச் சீர்திருத்தத்தை நடைமுறைப்படுத்தினார். இதனைத் தமிழ்நாடு அரசு 1978-ஆம் ஆண்டு அதிகாரப்பூர்வமாக ஏற்றுச் செயல்படுத்தியது.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - எழுத்துச் சீர்திருத்தம்"},{"id":89,"subject":"tamil","testNumber":1,"question":"தமிழில் நமக்குக் கிடைத்துள்ள மிகப் பழமையான இலக்கண நூலான தொல்காப்பியத்தின் எழுத்ததிகாரத்தில் எத்தனை இயல்கள் உள்ளன?","options":["5 இயல்கள்","7 இயல்கள்","10 இயல்கள்","9 இயல்கள்"],"correctAnswer":3,"explanation":"தொல்காப்பியம் எழுத்து, சொல், பொருள் என்ற மூன்று அதிகாரங்களைக் கொண்டது. ஒவ்வொரு அதிகாரத்திற்கும் 9 இயல்கள் வீதம் மொத்தம் 27 இயல்கள் உள்ளன. எழுத்ததிகாரம் நூன்மரபு முதல் குற்றியலுகரப் புணரியல் வரை 9 இயல்களைக் கொண்டுள்ளது.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - தொல்காப்பிய எழுத்ததிகாரம்"},{"id":90,"subject":"tamil","testNumber":1,"question":"தொல்காப்பியப் பிறப்பியலின்படி மெல்லின மெய்யெழுத்துகள் ஆறும் எந்த உறுப்பை இடமாகக் கொண்டு பிறக்கின்றன?","options":["மூக்கு","மார்பு","கழுத்து","தலை"],"correctAnswer":0,"explanation":"தொல்காப்பிய எழுத்ததிகாரப் பிறப்பியலின்படி உயிரெழுத்துகளும் இடையின மெய்களும் கழுத்தையும், வல்லின மெய்கள் மார்பையும், மெல்லின மெய்கள் மூக்கையும், ஆய்த எழுத்து தலையையும் இடமாகக் கொண்டு பிறக்கின்றன.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - தொல்காப்பிய எழுத்ததிகாரம்"},{"id":91,"subject":"tamil","testNumber":1,"question":"13-ஆம் நூற்றாண்டில் 'நன்னூல்' என்ற தமிழ் இலக்கண நூலை இயற்றியவர் யார்?","options":["தொல்காப்பியர்","பவணந்தி முனிவர்","அகத்தியர்","புத்தமித்திரர்"],"correctAnswer":1,"explanation":"'நன்னூல்' என்னும் புகழ்பெற்ற தமிழ் இலக்கண நூலை 13-ஆம் நூற்றாண்டில் பவணந்தி முனிவர் இயற்றினார். இந்நூல் எழுத்ததிகாரம், சொல்லதிகாரம் ஆகிய இரு அதிகாரங்களைக் கொண்டுள்ளது.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - நன்னூல் எழுத்ததிகாரம்"},{"id":92,"subject":"tamil","testNumber":1,"question":"நன்னூலின் எழுத்ததிகாரத்தில் அமைந்துள்ள இயல்களின் எண்ணிக்கை எவ்வளவு?","options":["மூன்று","நான்கு","ஐந்து","ஒன்பது"],"correctAnswer":2,"explanation":"நன்னூலின் எழுத்ததிகாரம் எழுத்தியல், பதவியல், உயிரீற்றுப் புணரியல், மெய்யீற்றுப் புணரியல், உருபுப் புணரியல் ஆகிய ஐந்து இயல்களைக் கொண்டுள்ளது. இதேபோல் சொல்லதிகாரமும் ஐந்து இயல்களைக் கொண்டுள்ளது.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - நன்னூல் எழுத்ததிகாரம்"},{"id":93,"subject":"tamil","testNumber":1,"question":"எழுத்துகளின் பிறப்புக் கொள்கைப்படி 'ஆய்த எழுத்து' எந்த உறுப்பை இடமாகக் கொண்டு பிறக்கிறது?","options":["கழுத்து","மார்பு","மூக்கு","தலை"],"correctAnswer":3,"explanation":"நன்னூல் மற்றும் தொல்காப்பியப் பிறப்பியல் கோட்பாட்டின்படி ஆய்த எழுத்து தலையை இடமாகக் கொண்டு, வாயைத் திறத்தல் என்ற முயற்சியால் பிறக்கிறது.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - தொல்காப்பிய எழுத்ததிகாரம்"},{"id":94,"subject":"tamil","testNumber":1,"question":"நன்னூல் குறிப்பிடும் 42 ஓரெழுத்து ஒருமொழிகளுள் குறில் எழுத்துகளாக அமைந்த இரு சொற்கள் எவை?","options":["நொ, து","கை, பை","மா, மீ","தீ, பூ"],"correctAnswer":0,"explanation":"நன்னூலார் தமிழில் 42 ஓரெழுத்து ஒருமொழிகள் உள்ளதாகக் குறிப்பிடுகிறார். அவற்றுள் 40 எழுத்துகள் நெடில்களாகவும், 'நொ' (துன்பம்), 'து' (உண்) ஆகிய இரண்டும் மட்டுமே குறில் எழுத்துகளாகவும் உள்ளன.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - தமிழின் வளமை"},{"id":95,"subject":"tamil","testNumber":1,"question":"தமிழ் மொழியின் நுட்பமான சொல்வளத்தைக் காட்டும் 'பூவின் ஏழு நிலைகள்' சரியான வரிசையில் அமைந்தது எது?","options":["மொட்டு, அரும்பு, முகை, அலர், மலர், வீ, செம்மல்","அரும்பு, முகை, மொட்டு, மலர், அலர், செம்மல், வீ","அரும்பு, மொட்டு, முகை, மலர், அலர், வீ, செம்மல்","அரும்பு, மொட்டு, மலர், முகை, அலர், வீ, செம்மல்"],"correctAnswer":2,"explanation":"பூவின் தோற்றம் முதல் வாடி உதிர்வது வரையிலான ஏழு நிலைகளுக்குத் தமிழில் தனித்தனிப் பெயர்கள் உள்ளன. அதன் சரியான வரிசை: அரும்பு -> மொட்டு -> முகை -> மலர் -> அலர் -> வீ -> செம்மல்.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - தமிழின் வளமை"},{"id":96,"subject":"tamil","testNumber":1,"question":"மொழிஞாயிறு தேவநேயப் பாவாணர் குறிப்பிட்ட தமிழ்ச் சொல்வளத்தின்படி, நெல் மற்றும் புல் ஆகியவற்றின் இலை எவ்வாறு அழைக்கப்படுகிறது?","options":["தோகை","ஓலை","சண்டு","தாள்"],"correctAnswer":3,"explanation":"தேவநேயப் பாவாணரின் 'தமிழ்ச் சொல்வளம்' விளக்கப்படி புளி, வேம்பு போன்றவற்றின் இலை 'இலை' என்றும்; நெல், புல் ஆகியவற்றின் இலை 'தாள்' என்றும்; சோளம், கரும்பு ஆகியவற்றின் இலை 'தோகை' என்றும்; தென்னை, பனை ஆகியவற்றின் இலை 'ஓலை' என்றும் அழைக்கப்படும்.","difficulty":"hard","topic":"தமிழ் மொழியின் சிறப்புகள் - தமிழின் வளமை"},{"id":97,"subject":"tamil","testNumber":1,"question":"தமிழ் எண் வடிவங்களில் 'எ' மற்றும் 'அ' ஆகிய எழுத்துகள் குறிக்கும் எண்கள் முறையே யாவை?","options":["7 மற்றும் 8","6 மற்றும் 7","8 மற்றும் 9","5 மற்றும் 8"],"correctAnswer":0,"explanation":"தமிழ் எண்களின் வரிசை: க(1), உ(2), ங(3), ச(4), ரு(5), சா(6), எ(7), அ(8), கூ(9), க0(10). இதன்படி 'எ' என்பது 7-ஐயும், 'அ' என்பது 8-ஐயும் குறிக்கின்றன.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - தமிழின் பழமை"},{"id":98,"subject":"tamil","testNumber":1,"question":"உலகத் தமிழ் மாநாடுகள் நடைபெறுவதற்கு அடித்தளமாக 'உலகத் தமிழ் ஆராய்ச்சி மன்றத்தை' (IATR) நிறுவியவர் யார்?","options":["மு. வரதராசனார்","வ.ஐ. சுப்பிரமணியம்","தனிநாயகம் அடிகள்","தெ.பொ. மீனாட்சிசுந்தரனார்"],"correctAnswer":2,"explanation":"உலக அளவில் தமிழ் ஆராய்ச்சியை வளர்க்கும் நோக்கில் 1964-ஆம் ஆண்டு 'உலகத் தமிழ் ஆராய்ச்சி மன்றத்தை' (International Association of Tamil Research) நிறுவியவர் தனிநாயகம் அடிகள் ஆவார்.","difficulty":"medium","topic":"தமிழ் மொழியின் சிறப்புகள் - உலகத் தமிழ் மாநாடுகள்"},{"id":99,"subject":"tamil","testNumber":1,"question":"முதல் உலகத் தமிழ் மாநாடு 1966-ஆம் ஆண்டு எந்த நகரத்தில் நடைபெற்றது?","options":["சென்னை","யாழ்ப்பாணம்","பாரிஸ்","கோலாலம்பூர்"],"correctAnswer":3,"explanation":"முதல் உலகத் தமிழ் மாநாடு 1966-ஆம் ஆண்டு மலேசியாவின் தலைநகரான கோலாலம்பூரில் நடைபெற்றது. இரண்டாவது மாநாடு 1968-இல் சென்னையிலும், மூன்றாவது 1970-இல் பாரிஸிலும், நான்காவது 1974-இல் யாழ்ப்பாணத்திலும் நடைபெற்றன.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - உலகத் தமிழ் மாநாடுகள்"},{"id":100,"subject":"tamil","testNumber":1,"question":"உலகத் தமிழ்ச் செம்மொழி மாநாடு 2010-ஆம் ஆண்டு தமிழ்நாட்டின் எந்த நகரத்தில் நடைபெற்றது?","options":["கோயம்புத்தூர்","மதுரை","தஞ்சாவூர்","திருச்சிராப்பள்ளி"],"correctAnswer":0,"explanation":"தமிழ் செம்மொழியாக அறிவிக்கப்பட்டதைப் போற்றும் வகையில் 'உலகத் தமிழ்ச் செம்மொழி மாநாடு' 2010-ஆம் ஆண்டு ஜூன் 23 முதல் 27 வரை தமிழ்நாட்டின் கோயம்புத்தூர் நகரத்தில் சிறப்பாக நடைபெற்றது.","difficulty":"easy","topic":"தமிழ் மொழியின் சிறப்புகள் - உலகத் தமிழ் மாநாடுகள்"}]);
